from django.db.models import FilteredRelation, Q
from django.test import TestCase

from .models import Author, Book, Editor


class ReproTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.editor = Editor.objects.create(name="a")
        cls.author1 = Author.objects.create(name="Alice")
        cls.author2 = Author.objects.create(name="Jane")
        cls.book1 = Book.objects.create(
            title="Poem by Alice", editor=cls.editor, author=cls.author1
        )
        cls.book2 = Book.objects.create(
            title="The book by Jane", editor=cls.editor, author=cls.author2
        )

    def test_multiple_filtered_relations_same_relation(self):
        qs = Author.objects.alias(
            book_alice=FilteredRelation(
                "book", condition=Q(book__title__icontains="alice")
            ),
            book_jane=FilteredRelation(
                "book", condition=Q(book__title__icontains="jane")
            ),
        )
        print("====SQL====")
        print(str(qs.query))
        print("====JOIN COUNT====", str(qs.query).count("JOIN"))
        print("====RESULTS====")
        print(
            sorted(
                qs.annotate(
                    n_alice=FilteredRelation(
                        "book", condition=Q(book__title__icontains="alice")
                    )
                ).values_list("name", flat=True)
            )
        )
EOF
